/**
 * M1 relational schema (architecture §6). Conventions:
 * - UUIDv7 primary keys generated by Postgres 18 (`uuidv7()`): time-ordered, no global sequences.
 * - Every work-scoped table carries `work_id`: it is the future shard key (P-025, architecture §20).
 * - Document content lives only in `document_states` and is written only by the collaboration service (P-013).
 * - User ids are text because the auth library owns the users table.
 */
import { sql } from 'drizzle-orm'
import { user } from './auth-schema.ts'
import {
  bigint,
  boolean,
  customType,
  date,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core'

// drizzle-orm 0.45 has no native bytea; customType is the documented route.
const bytea = customType<{ data: Uint8Array; driverData: Buffer }>({
  dataType: () => 'bytea',
  toDriver: (v) => Buffer.from(v.buffer, v.byteOffset, v.byteLength),
  fromDriver: (v) => new Uint8Array(v.buffer, v.byteOffset, v.byteLength),
})

// Fractional-index keys must compare byte by byte; the database's default collation would misorder them
// (e.g. place "a0" before "Zz"), so position columns use the "C" collation.
const byteOrderedText = customType<{ data: string }>({ dataType: () => 'text COLLATE "C"' })

const tsvector = customType<{ data: string }>({ dataType: () => 'tsvector' })

const id = () =>
  uuid('id')
    .primaryKey()
    .default(sql`uuidv7()`)
const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow()
const updatedAt = () => timestamp('updated_at', { withTimezone: true }).notNull().defaultNow()

export const visibility = pgEnum('visibility', ['private', 'unlisted', 'public'])
export const participation = pgEnum('participation', ['none', 'propose', 'branch', 'propose_and_branch'])
// PRD FR-004 categories (novella and collection kept from earlier; the column keeps its original name `form`).
export const workForm = pgEnum('work_form', [
  'novel',
  'novella',
  'short_story',
  'collection',
  'essay',
  'article',
  'other',
  'fiction',
  'poetry',
  'research_paper',
  'educational',
  'general_document',
])
export const collaborationMode = pgEnum('collaboration_mode', ['direct', 'mixed', 'proposal'])
export const workLicense = pgEnum('work_license', [
  'all_rights_reserved',
  'cc_by',
  'cc_by_sa',
  'cc_by_nc',
  'cc_by_nc_sa',
  'cc0',
])
export const memberRole = pgEnum('member_role', ['owner', 'editor', 'collaborator', 'contributor', 'viewer'])
export const documentKind = pgEnum('document_kind', ['chapter', 'proposal'])
export const branchStatus = pgEnum('branch_status', ['active', 'abandoned', 'selected'])
export const snapshotReason = pgEnum('snapshot_reason', [
  'auto',
  'manual',
  'publish',
  'proposal_base',
  'proposal_applied',
  'branch_fork',
  'pre_restore',
  'pre_migration',
])

export const works = pgTable(
  'works',
  {
    id: id(),
    ownerId: text('owner_id')
      .notNull()
      .references(() => user.id),
    title: text('title').notNull(),
    slug: text('slug').notNull(),
    description: text('description').notNull().default(''),
    form: workForm('form').notNull().default('novel'),
    // Private by default (P-018): making a work public is always an explicit, audited action.
    visibility: visibility('visibility').notNull().default('private'),
    participation: participation('participation').notNull().default('none'),
    collaborationMode: collaborationMode('collaboration_mode').notNull().default('direct'),
    tags: text('tags')
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    contentWarnings: text('content_warnings')
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    // Conservative default (PRD §19): nobody surrenders copyright by participating.
    /** passage reactions this work offers (FR-017); empty turns reactions off */
    reactionKinds: text('reaction_kinds')
      .array()
      .notNull()
      .default(sql`'{beautiful_line,plot_twist,interesting_idea,needs_clarity,important_detail}'::text[]`),
    license: workLicense('license').notNull().default('all_rights_reserved'),
    /** short, unguessable id for public URLs: /works/{slug}-{publicId} */
    publicId: text('public_id')
      .notNull()
      .unique()
      .default(sql`substr(md5(random()::text || clock_timestamp()::text), 1, 10)`),
    publishedAt: timestamp('published_at', { withTimezone: true }),
    /** the writer says it's finished (readers see "Complete"; otherwise "Ongoing") */
    completedAt: timestamp('completed_at', { withTimezone: true }),
    /** denormalised for the feed; kept in step with work_likes / work_views / reader_comments in the same transaction */
    likeCount: integer('like_count').notNull().default(0),
    viewCount: integer('view_count').notNull().default(0),
    readerCommentCount: integer('reader_comment_count').notNull().default(0),
    /** the writer's cover choice (palette, motif, layout); null = generated from the id. Validated as CoverConfig. */
    cover: jsonb('cover'),
    /**
     * Classics (P-063): where a public-domain work came from, e.g. { kind: 'public_domain', originalAuthor, year }.
     * Null for everything people write here.
     */
    source: jsonb('source'),
    /** a serial's release day (P-057): 0 = Sunday … 6 = Saturday; null = no schedule */
    releaseDay: integer('release_day'),
    /** open calls (P-058): roles the writer is looking for, e.g. illustrator, editor */
    openRoles: text('open_roles')
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    /** set by moderation (FR-031): hidden works leave every public surface until restored */
    hiddenAt: timestamp('hidden_at', { withTimezone: true }),
    /**
     * Search (FR-021): title, then description, then tags, weighted. The 'simple' configuration keeps it language-
     * neutral (no English-only stemming). Maintained by Postgres; queried with websearch_to_tsquery, which never errors.
     */
    searchVector: tsvector('search_vector').generatedAlwaysAs(
      // morrow_tags_text: an immutable wrapper (array_to_string is only "stable"), created by this column's migration.
      sql`setweight(to_tsvector('simple'::regconfig, coalesce(title, '')), 'A') || setweight(to_tsvector('simple'::regconfig, coalesce(description, '')), 'B') || setweight(to_tsvector('simple'::regconfig, morrow_tags_text(tags)), 'C')`,
    ),
    defaultBranchId: uuid('default_branch_id'),
    version: integer('version').notNull().default(1), // optimistic concurrency for settings (If-Match)
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    deletedAt: timestamp('deleted_at', { withTimezone: true }),
  },
  (t) => [
    index('works_owner_idx').on(t.ownerId, t.updatedAt),
    index('works_search_idx').using('gin', t.searchVector),
    // Discovery lists: public, published, visible, newest first.
    index('works_discovery_idx')
      .on(t.publishedAt)
      .where(
        sql`${t.visibility} = 'public' and ${t.publishedAt} is not null and ${t.deletedAt} is null and ${t.hiddenAt} is null`,
      ),
  ],
)

export const workMembers = pgTable(
  'work_members',
  {
    workId: uuid('work_id')
      .notNull()
      .references(() => works.id),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    role: memberRole('role').notNull(),
    grantedBy: text('granted_by').notNull(),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.workId, t.userId] }), index('work_members_user_idx').on(t.userId)],
)

export const branches = pgTable(
  'branches',
  {
    id: id(),
    workId: uuid('work_id')
      .notNull()
      .references(() => works.id),
    parentBranchId: uuid('parent_branch_id'),
    name: text('name').notNull(),
    slug: text('slug').notNull(),
    description: text('description').notNull().default(''),
    /** FR-018: active, abandoned, or selected (at most one selected per work: the version chosen for publication) */
    status: branchStatus('status').notNull().default('active'),
    createdBy: text('created_by').notNull(),
    isDefault: boolean('is_default').notNull().default(false),
    visibility: visibility('visibility').notNull().default('private'),
    forkedAt: timestamp('forked_at', { withTimezone: true }),
    /** display lineage: the chapter (in the parent branch) where this branch takes a different direction */
    divergesAtChapterId: uuid('diverges_at_chapter_id'),
    createdAt: createdAt(),
    archivedAt: timestamp('archived_at', { withTimezone: true }),
  },
  (t) => [
    index('branches_work_idx').on(t.workId),
    uniqueIndex('branches_one_default_per_work')
      .on(t.workId)
      .where(sql`${t.isDefault}`),
    uniqueIndex('branches_one_selected_per_work')
      .on(t.workId)
      .where(sql`${t.status} = 'selected'`),
  ],
)

export const documents = pgTable(
  'documents',
  {
    id: id(),
    workId: uuid('work_id')
      .notNull()
      .references(() => works.id),
    kind: documentKind('kind').notNull(),
    schemaVersion: integer('schema_version').notNull(),
    createdAt: createdAt(),
  },
  (t) => [index('documents_work_idx').on(t.workId)],
)

export const chapters = pgTable(
  'chapters',
  {
    id: id(),
    workId: uuid('work_id')
      .notNull()
      .references(() => works.id),
    branchId: uuid('branch_id')
      .notNull()
      .references(() => branches.id),
    documentId: uuid('document_id')
      .notNull()
      .references(() => documents.id),
    title: text('title').notNull(),
    description: text('description').notNull().default(''),
    /** FR-006 section-level collaboration setting; null inherits the work's mode */
    collaborationMode: collaborationMode('collaboration_mode'),
    /** fractional index: lexicographic order, so concurrent reorders never renumber siblings */
    position: byteOrderedText('position').notNull(),
    originChapterId: uuid('origin_chapter_id'),
    forkSnapshotId: uuid('fork_snapshot_id'),
    /**
     * Branch merges (FR-018): this chapter's state as of its last merge into the parent. The next merge compares
     * from here, so the parent's own edits since then are never mistaken for this branch's changes.
     * Null until the first merge (then the fork snapshot is the base).
     */
    mergeBaseSnapshotId: uuid('merge_base_snapshot_id'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    deletedAt: timestamp('deleted_at', { withTimezone: true }),
  },
  (t) => [
    index('chapters_branch_order_idx').on(t.workId, t.branchId, t.position),
    uniqueIndex('chapters_document_uq').on(t.documentId),
  ],
)

export const documentStates = pgTable('document_states', {
  documentId: uuid('document_id')
    .primaryKey()
    .references(() => documents.id),
  workId: uuid('work_id').notNull(),
  state: bytea('state').notNull(),
  stateVector: bytea('state_vector').notNull(),
  revision: bigint('revision', { mode: 'number' }).notNull(),
  byteSize: integer('byte_size').notNull(),
  /** size right after the last compaction; merge-on-write grows state until compacted (spike S1) */
  compactedSize: integer('compacted_size').notNull(),
  updatedAt: updatedAt(),
})

export const documentSnapshots = pgTable(
  'document_snapshots',
  {
    id: id(),
    documentId: uuid('document_id')
      .notNull()
      .references(() => documents.id),
    workId: uuid('work_id').notNull(),
    state: bytea('state').notNull(),
    contentJson: jsonb('content_json').notNull(),
    contentHash: text('content_hash').notNull(),
    wordCount: integer('word_count').notNull(),
    reason: snapshotReason('reason').notNull(),
    label: text('label'),
    createdBy: text('created_by'),
    createdAt: createdAt(),
  },
  (t) => [index('snapshots_document_idx').on(t.workId, t.documentId, t.createdAt)],
)

export const documentProjections = pgTable('document_projections', {
  documentId: uuid('document_id')
    .primaryKey()
    .references(() => documents.id),
  workId: uuid('work_id').notNull(),
  contentJson: jsonb('content_json').notNull(),
  plainText: text('plain_text').notNull(),
  wordCount: integer('word_count').notNull(),
  sourceRevision: bigint('source_revision', { mode: 'number' }).notNull(),
  projectedAt: timestamp('projected_at', { withTimezone: true }).notNull().defaultNow(),
})

/** Append-only audit trail; doubles as the outbox until a queue is warranted (architecture §20). */
export const activityEvents = pgTable(
  'activity_events',
  {
    id: id(),
    workId: uuid('work_id'),
    actorId: text('actor_id'),
    type: text('type').notNull(),
    subjectType: text('subject_type').notNull(),
    subjectId: text('subject_id').notNull(),
    data: jsonb('data').notNull().default({}),
    createdAt: createdAt(),
    processedAt: timestamp('processed_at', { withTimezone: true }),
  },
  (t) => [
    index('activity_work_idx').on(t.workId, t.createdAt),
    index('activity_unprocessed_idx')
      .on(t.createdAt)
      .where(sql`${t.processedAt} is null`),
  ],
)

/** Replay protection for create/accept/fork operations (P-025): the same key returns the same response. */
export const idempotencyKeys = pgTable(
  'idempotency_keys',
  {
    userId: text('user_id').notNull(),
    key: text('key').notNull(),
    route: text('route').notNull(),
    requestHash: text('request_hash').notNull(),
    status: integer('status').notNull(),
    body: jsonb('body').notNull(),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.key] })],
)

/** Pending membership (M2). The token is a bearer secret: only its SHA-256 is stored. */
export const invitations = pgTable(
  'invitations',
  {
    id: id(),
    workId: uuid('work_id')
      .notNull()
      .references(() => works.id),
    email: text('email').notNull(),
    role: memberRole('role').notNull(),
    tokenHash: text('token_hash').notNull(),
    invitedBy: text('invited_by').notNull(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    acceptedAt: timestamp('accepted_at', { withTimezone: true }),
    acceptedBy: text('accepted_by'),
    revokedAt: timestamp('revoked_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex('invitations_token_uq').on(t.tokenHash),
    index('invitations_work_idx').on(t.workId, t.createdAt),
  ],
)

/**
 * "What if" reader polls (P-062): a question at the end of a chapter, with two to four answers. Readers vote once
 * (and may change their mind); the writer sees which way readers lean. One poll per chapter.
 */
export const chapterPolls = pgTable('chapter_polls', {
  id: id(),
  workId: uuid('work_id')
    .notNull()
    .references(() => works.id, { onDelete: 'cascade' }),
  chapterId: uuid('chapter_id')
    .notNull()
    .unique()
    .references(() => chapters.id, { onDelete: 'cascade' }),
  question: text('question').notNull(),
  options: text('options').array().notNull(),
  closesAt: timestamp('closes_at', { withTimezone: true }),
  createdBy: text('created_by').notNull(),
  createdAt: createdAt(),
})
export const pollVotes = pgTable(
  'poll_votes',
  {
    pollId: uuid('poll_id')
      .notNull()
      .references(() => chapterPolls.id, { onDelete: 'cascade' }),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    option: integer('option').notNull(),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.pollId, t.userId] })],
)

/**
 * Words written per person per day (P-055), reported by the editor from the writer's own edits (never others' in the
 * same document). `day` is the writer's local date, so a streak follows their clock, not the server's.
 */
export const writingLog = pgTable(
  'writing_log',
  {
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    day: date('day').notNull(),
    words: integer('words').notNull().default(0),
    updatedAt: updatedAt(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.day] })],
)

/** "Tell me when it's ready": people waiting for a feature that's coming (comics first). */
export const featureWaitlist = pgTable(
  'feature_waitlist',
  {
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    feature: text('feature').notNull(),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.feature] })],
)

/**
 * "Ask to collaborate" on a published work (P-050): anyone signed in may ask; the owner or an editor accepts (the person
 * joins as a contributor) or declines. One pending request per person per work.
 */
export const contributionRequests = pgTable(
  'contribution_requests',
  {
    id: id(),
    workId: uuid('work_id')
      .notNull()
      .references(() => works.id, { onDelete: 'cascade' }),
    requesterId: text('requester_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    message: text('message').notNull().default(''),
    /** pending | accepted | declined | withdrawn */
    status: text('status').notNull().default('pending'),
    decidedBy: text('decided_by'),
    decidedAt: timestamp('decided_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex('contribution_requests_one_pending')
      .on(t.workId, t.requesterId)
      .where(sql`status = 'pending'`),
    index('contribution_requests_work_idx').on(t.workId, t.status, t.createdAt),
  ],
)

/** Trustworthy "who edited what, when", recorded by collab (attribution groundwork, architecture §6). */
export const editSessions = pgTable(
  'edit_sessions',
  {
    id: id(),
    documentId: uuid('document_id')
      .notNull()
      .references(() => documents.id),
    workId: uuid('work_id').notNull(),
    userId: text('user_id').notNull(),
    startedAt: timestamp('started_at', { withTimezone: true }).notNull(),
    endedAt: timestamp('ended_at', { withTimezone: true }).notNull(),
    updateCount: integer('update_count').notNull(),
  },
  (t) => [index('edit_sessions_document_idx').on(t.workId, t.documentId, t.startedAt)],
)

/** Public profile (FR-002), kept apart from the auth library's user table. */
export const profiles = pgTable('profiles', {
  userId: text('user_id')
    .primaryKey()
    .references(() => user.id, { onDelete: 'cascade' }),
  /** lowercase, unique, url-safe */
  username: text('username').notNull().unique(),
  bio: text('bio').notNull().default(''),
  interests: text('interests')
    .array()
    .notNull()
    .default(sql`'{}'::text[]`),
  genres: text('genres')
    .array()
    .notNull()
    .default(sql`'{}'::text[]`),
  links: jsonb('links').notNull().default([]),
  avatarSeed: text('avatar_seed')
    .notNull()
    .default(sql`substr(md5(random()::text), 1, 8)`),
  // Users control which profile information is public (FR-002).
  isPublic: boolean('is_public').notNull().default(true),
  showBio: boolean('show_bio').notNull().default(true),
  showInterests: boolean('show_interests').notNull().default(true),
  showLinks: boolean('show_links').notNull().default(true),
  /** FR-022: whether follower and following counts are shown on the public profile */
  showFollows: boolean('show_follows').notNull().default(true),
  /** the avatar the person built (see contracts `AvatarConfig`); null = initials on a colour from the seed */
  avatar: jsonb('avatar').$type<Record<string, unknown> | null>(),
  /** FR-025: whether earned badges show on the public profile */
  showBadges: boolean('show_badges').notNull().default(true),
  /** words a day the writer is aiming for (P-055); 0 = no goal */
  dailyWordGoal: integer('daily_word_goal').notNull().default(0),
  onboardedAt: timestamp('onboarded_at', { withTimezone: true }),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
})

/**
 * What readers see (FR-023, P-014). Each row pins a chapter's *snapshot* and also its title and order as published,
 * so later draft edits — even renames — never reach readers until the work is republished.
 */
export const publications = pgTable(
  'publications',
  {
    id: id(),
    workId: uuid('work_id')
      .notNull()
      .references(() => works.id),
    branchId: uuid('branch_id')
      .notNull()
      .references(() => branches.id),
    chapterId: uuid('chapter_id')
      .notNull()
      .references(() => chapters.id),
    snapshotId: uuid('snapshot_id')
      .notNull()
      .references(() => documentSnapshots.id),
    title: text('title').notNull(),
    position: byteOrderedText('position').notNull(),
    wordCount: integer('word_count').notNull(),
    publishedBy: text('published_by').notNull(),
    publishedAt: timestamp('published_at', { withTimezone: true }).notNull().defaultNow(),
    /** set when a newer publication replaces this one, or the work is unpublished */
    supersededAt: timestamp('superseded_at', { withTimezone: true }),
  },
  (t) => [
    index('publications_live_idx')
      .on(t.workId, t.position)
      .where(sql`${t.supersededAt} is null`),
  ],
)

// ---- Proposals (PRD FR-014/015, architecture §9) ----
export const proposalKind = pgEnum('proposal_kind', [
  'edit',
  'outline',
  'character',
  'research',
  'feedback',
  'chapter',
])
export const proposalStatus = pgEnum('proposal_status', [
  'draft',
  'submitted',
  'under_review',
  'changes_requested',
  'accepted',
  'rejected',
  'withdrawn',
  'superseded',
])

export const proposals = pgTable(
  'proposals',
  {
    id: id(),
    workId: uuid('work_id')
      .notNull()
      .references(() => works.id),
    kind: proposalKind('kind').notNull(),
    status: proposalStatus('status').notNull().default('draft'),
    authorId: text('author_id').notNull(),
    title: text('title').notNull(),
    /** the author's "why" */
    explanation: text('explanation').notNull().default(''),
    /** content of note-type contributions (outline, character, research, feedback); edits keep content in the workspace */
    body: text('body').notNull().default(''),
    /** the chapter it concerns: required for edits, optional context for notes */
    chapterId: uuid('chapter_id').references(() => chapters.id),
    /** edits: the private workspace document, forked from the chapter with its Yjs history */
    workspaceDocumentId: uuid('workspace_document_id').references(() => documents.id),
    /** edits: the chapter state the proposal started from (refreshed when the author brings in newer text) */
    baseSnapshotId: uuid('base_snapshot_id').references(() => documentSnapshots.id),
    submittedSnapshotId: uuid('submitted_snapshot_id').references(() => documentSnapshots.id),
    appliedSnapshotId: uuid('applied_snapshot_id').references(() => documentSnapshots.id),
    reviewerId: text('reviewer_id'),
    submittedAt: timestamp('submitted_at', { withTimezone: true }),
    decidedAt: timestamp('decided_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('proposals_work_status_idx').on(t.workId, t.status, t.createdAt),
    index('proposals_author_idx').on(t.workId, t.authorId),
    uniqueIndex('proposals_workspace_idx').on(t.workspaceDocumentId),
  ],
)

/** Everything that happened to a proposal: status changes and review comments (FR-015 "history", auditable). */
export const proposalEvents = pgTable(
  'proposal_events',
  {
    id: id(),
    proposalId: uuid('proposal_id')
      .notNull()
      .references(() => proposals.id),
    workId: uuid('work_id').notNull(),
    actorId: text('actor_id').notNull(),
    type: text('type').$type<'comment' | 'status'>().notNull(),
    body: text('body').notNull().default(''),
    fromStatus: proposalStatus('from_status'),
    toStatus: proposalStatus('to_status'),
    createdAt: createdAt(),
  },
  (t) => [index('proposal_events_proposal_idx').on(t.proposalId, t.createdAt)],
)

// ---- Feedback: inline comments and passage reactions (PRD FR-016/017) ----
/**
 * Where a comment points. `start`/`end` are Yjs relative positions (JSON): they follow the text through every
 * concurrent edit. `quote` and `blockId` are what the passage said and where, for display and when the text is gone.
 */
export interface CommentAnchor {
  start: unknown
  end: unknown
  quote: string
  blockId: string | null
}

export const comments = pgTable(
  'comments',
  {
    id: id(),
    workId: uuid('work_id')
      .notNull()
      .references(() => works.id),
    documentId: uuid('document_id')
      .notNull()
      .references(() => documents.id),
    /** null for a thread's first comment */
    parentId: uuid('parent_id'),
    authorId: text('author_id').notNull(),
    body: text('body').notNull(),
    /** user ids @mentioned (resolved against the work's members at write time) */
    mentions: text('mentions')
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    anchor: jsonb('anchor').$type<CommentAnchor>(),
    resolvedAt: timestamp('resolved_at', { withTimezone: true }),
    resolvedBy: text('resolved_by'),
    editedAt: timestamp('edited_at', { withTimezone: true }),
    deletedAt: timestamp('deleted_at', { withTimezone: true }),
    deletedBy: text('deleted_by'),
    createdAt: createdAt(),
  },
  (t) => [
    index('comments_document_idx').on(t.workId, t.documentId, t.createdAt),
    index('comments_parent_idx').on(t.parentId),
  ],
)

export const reactions = pgTable(
  'reactions',
  {
    id: id(),
    workId: uuid('work_id')
      .notNull()
      .references(() => works.id),
    documentId: uuid('document_id')
      .notNull()
      .references(() => documents.id),
    /** reactions attach to a paragraph (block id): stable through edits, and counts stay meaningful */
    blockId: text('block_id').notNull(),
    userId: text('user_id').notNull(),
    kind: text('kind').notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    // One of each kind per person per paragraph (FR-017 abuse prevention).
    uniqueIndex('reactions_unique_idx').on(t.documentId, t.blockId, t.userId, t.kind),
    index('reactions_document_idx').on(t.workId, t.documentId),
  ],
)

/** When each person last looked at a chapter's feedback, for the "new feedback" signal. */
export const feedbackReads = pgTable(
  'feedback_reads',
  {
    userId: text('user_id').notNull(),
    documentId: uuid('document_id')
      .notNull()
      .references(() => documents.id),
    seenAt: timestamp('seen_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.documentId] })],
)

/** A record of each merge attempt (FR-018 "merge operations detect conflicts"): what applied, what conflicted. */
export const branchMerges = pgTable(
  'branch_merges',
  {
    id: id(),
    workId: uuid('work_id')
      .notNull()
      .references(() => works.id),
    sourceBranchId: uuid('source_branch_id')
      .notNull()
      .references(() => branches.id),
    targetBranchId: uuid('target_branch_id')
      .notNull()
      .references(() => branches.id),
    mergedBy: text('merged_by').notNull(),
    status: text('status').$type<'merged' | 'conflict' | 'partial'>().notNull(),
    report: jsonb('report').notNull().default({}),
    createdAt: createdAt(),
  },
  (t) => [index('branch_merges_source_idx').on(t.workId, t.sourceBranchId, t.createdAt)],
)

// ---- Notifications (PRD FR-030) ----
export const NOTIFICATION_CATEGORIES = [
  'invitations',
  'proposals',
  'comments',
  'mentions',
  'publishing',
  'activity',
] as const
export type NotificationCategory = (typeof NOTIFICATION_CATEGORIES)[number]

/**
 * One row per person per event worth telling them about, produced from the activity outbox. `dedupeKey` is unique
 * per recipient, so the same event (or a reply that is also a mention) is never delivered twice.
 */
export const notifications = pgTable(
  'notifications',
  {
    id: id(),
    userId: text('user_id').notNull(),
    category: text('category').$type<NotificationCategory>().notNull(),
    type: text('type').notNull(),
    workId: uuid('work_id'),
    actorId: text('actor_id'),
    /** rendered when created, so the list needs no joins */
    title: text('title').notNull(),
    body: text('body').notNull().default(''),
    /** in-app path to the thing it's about */
    url: text('url').notNull(),
    dedupeKey: text('dedupe_key').notNull(),
    readAt: timestamp('read_at', { withTimezone: true }),
    /** none: no email wanted; pending: waiting (e.g. quiet hours); sent; failed */
    emailState: text('email_state').$type<'none' | 'pending' | 'sent' | 'failed'>().notNull().default('none'),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex('notifications_dedupe_idx').on(t.userId, t.dedupeKey),
    index('notifications_user_idx').on(t.userId, t.createdAt),
    index('notifications_unread_idx')
      .on(t.userId)
      .where(sql`${t.readAt} is null`),
    index('notifications_email_pending_idx')
      .on(t.createdAt)
      .where(sql`${t.emailState} = 'pending'`),
  ],
)

/** Per-category choices (in-app, email) and quiet hours (FR-030). Absent means defaults. */
export const notificationPreferences = pgTable('notification_preferences', {
  userId: text('user_id')
    .primaryKey()
    .references(() => user.id, { onDelete: 'cascade' }),
  categories: jsonb('categories')
    .$type<Partial<Record<NotificationCategory, { inApp: boolean; email: boolean }>>>()
    .notNull()
    .default({}),
  /** minutes after local midnight; both null means no quiet hours */
  quietStart: integer('quiet_start'),
  quietEnd: integer('quiet_end'),
  timeZone: text('time_zone').notNull().default('UTC'),
  updatedAt: updatedAt(),
})

// ---- Following and bookmarks (PRD FR-022) ----
export const follows = pgTable(
  'follows',
  {
    followerId: text('follower_id').notNull(),
    /** an author (user id) or a work (work id) */
    targetType: text('target_type').$type<'author' | 'work'>().notNull(),
    targetId: text('target_id').notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    primaryKey({ columns: [t.followerId, t.targetType, t.targetId] }),
    index('follows_target_idx').on(t.targetType, t.targetId),
  ],
)

export const bookmarks = pgTable(
  'bookmarks',
  {
    userId: text('user_id').notNull(),
    workId: uuid('work_id')
      .notNull()
      .references(() => works.id),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.workId] })],
)

/** Editorial picks for discovery (FR-020), kept apart from algorithmic ranking and labelled as such. */
export const featuredWorks = pgTable('featured_works', {
  workId: uuid('work_id')
    .primaryKey()
    .references(() => works.id),
  /** a line from the curator, shown with the pick */
  note: text('note').notNull().default(''),
  featuredBy: text('featured_by').notNull(),
  featuredAt: timestamp('featured_at', { withTimezone: true }).notNull().defaultNow(),
})

// ---- Moderation and safety (PRD FR-031/032) ----
/** Platform staff. Granted outside the app (`pnpm --filter @morrow/api staff`), never self-service. */
export const staff = pgTable('staff', {
  userId: text('user_id')
    .primaryKey()
    .references(() => user.id, { onDelete: 'cascade' }),
  role: text('role').$type<'moderator' | 'admin'>().notNull(),
  grantedBy: text('granted_by'),
  createdAt: createdAt(),
})

export const REPORT_CATEGORIES = [
  'abuse',
  'harassment',
  'spam',
  'copyright',
  'impersonation',
  'inappropriate',
  'malicious_links',
  'other',
] as const
export const REPORT_TARGETS = ['work', 'comment', 'user', 'proposal', 'reader_comment'] as const

export const reports = pgTable(
  'reports',
  {
    id: id(),
    reporterId: text('reporter_id').notNull(),
    targetType: text('target_type').$type<(typeof REPORT_TARGETS)[number]>().notNull(),
    targetId: text('target_id').notNull(),
    /** the work it belongs to, when there is one */
    workId: uuid('work_id'),
    /** the person responsible for the reported thing */
    subjectUserId: text('subject_user_id'),
    category: text('category').$type<(typeof REPORT_CATEGORIES)[number]>().notNull(),
    details: text('details').notNull().default(''),
    /**
     * What was reported, as it was then. Moderators review this, never the whole private work: the documented
     * policy for private content (FR-031).
     */
    snapshot: jsonb('snapshot').notNull(),
    status: text('status').$type<'open' | 'reviewing' | 'actioned' | 'dismissed'>().notNull().default('open'),
    /** shown to the reporter */
    resolution: text('resolution').notNull().default(''),
    reviewerId: text('reviewer_id'),
    createdAt: createdAt(),
    resolvedAt: timestamp('resolved_at', { withTimezone: true }),
  },
  (t) => [
    index('reports_queue_idx').on(t.status, t.createdAt),
    // One open report per person per thing: repeat reports don't flood the queue.
    uniqueIndex('reports_open_once_idx')
      .on(t.reporterId, t.targetType, t.targetId)
      .where(sql`${t.status} in ('open', 'reviewing')`),
  ],
)

/** Every moderator action, append-only (FR-031 audit history). Reversals are new actions referencing the original. */
export const moderationActions = pgTable(
  'moderation_actions',
  {
    id: id(),
    moderatorId: text('moderator_id').notNull(),
    action: text('action')
      .$type<
        | 'hide_work'
        | 'restore_work'
        | 'remove_comment'
        | 'restore_comment'
        | 'restrict_account'
        | 'lift_restriction'
        | 'dismiss_report'
      >()
      .notNull(),
    targetType: text('target_type').notNull(),
    targetId: text('target_id').notNull(),
    subjectUserId: text('subject_user_id'),
    reportId: uuid('report_id'),
    reason: text('reason').notNull(),
    reverses: uuid('reverses'),
    createdAt: createdAt(),
  },
  (t) => [
    index('moderation_actions_target_idx').on(t.targetType, t.targetId, t.createdAt),
    index('moderation_actions_subject_idx').on(t.subjectUserId, t.createdAt),
  ],
)

/** Account-level restrictions (FR-031/032), enforced server-side. `suspended`: read-only; `muted`: no new comments, proposals or invitations. */
export const accountRestrictions = pgTable(
  'account_restrictions',
  {
    id: id(),
    userId: text('user_id').notNull(),
    kind: text('kind').$type<'suspended' | 'muted'>().notNull(),
    reason: text('reason').notNull(),
    actionId: uuid('action_id').notNull(),
    until: timestamp('until', { withTimezone: true }),
    liftedAt: timestamp('lifted_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index('account_restrictions_user_idx').on(t.userId)],
)

export const appeals = pgTable(
  'appeals',
  {
    id: id(),
    actionId: uuid('action_id').notNull(),
    userId: text('user_id').notNull(),
    message: text('message').notNull(),
    status: text('status').$type<'open' | 'upheld' | 'overturned'>().notNull().default('open'),
    decision: text('decision').notNull().default(''),
    decidedBy: text('decided_by'),
    createdAt: createdAt(),
    decidedAt: timestamp('decided_at', { withTimezone: true }),
  },
  // One appeal per action.
  (t) => [uniqueIndex('appeals_once_idx').on(t.actionId, t.userId)],
)

/** Blocking (FR-032). */
export const blocks = pgTable(
  'blocks',
  {
    blockerId: text('blocker_id').notNull(),
    blockedId: text('blocked_id').notNull(),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.blockerId, t.blockedId] }), index('blocks_blocked_idx').on(t.blockedId)],
)

// ---- Plans and entitlements (PRD FR-033/034) ----
/**
 * Limits are data, not code (PRD §18): edited by admins, read by the entitlement check. `null` means unlimited.
 * Prices and limits are validation hypotheses, not commitments.
 */
export interface PlanLimits {
  privateWorks: number | null
  membersPerWork: number | null
  branchesPerWork: number | null
  exportFormats: string[]
  aiCreditsPerMonth: number | null
}
export const plans = pgTable('plans', {
  key: text('key').primaryKey(),
  name: text('name').notNull(),
  description: text('description').notNull().default(''),
  /** minor units (cents); null = free or not for sale */
  priceMonthly: integer('price_monthly'),
  currency: text('currency').notNull().default('USD'),
  limits: jsonb('limits').$type<PlanLimits>().notNull(),
  /** feature flags this plan unlocks, e.g. 'advanced_history' */
  features: text('features')
    .array()
    .notNull()
    .default(sql`'{}'::text[]`),
  /** shown on the plans page and assignable */
  active: boolean('active').notNull().default(true),
  sortOrder: integer('sort_order').notNull().default(0),
  updatedAt: updatedAt(),
})

/** A person's plan. Without a row, they're on the default (free) plan. Billing may be disabled: then only comps exist. */
export const subscriptions = pgTable(
  'subscriptions',
  {
    id: id(),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    planKey: text('plan_key')
      .notNull()
      .references(() => plans.key),
    status: text('status').$type<'active' | 'trialing' | 'past_due' | 'canceled' | 'comped'>().notNull(),
    /** where it came from: an admin's comp, or a payment provider */
    source: text('source').$type<'comp' | 'provider'>().notNull(),
    providerRef: text('provider_ref'),
    currentPeriodEnd: timestamp('current_period_end', { withTimezone: true }),
    cancelAtPeriodEnd: boolean('cancel_at_period_end').notNull().default(false),
    grantedBy: text('granted_by'),
    note: text('note').notNull().default(''),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex('subscriptions_user_idx').on(t.userId)],
)

/** Billing history (FR-033), filled by provider webhooks once billing is enabled. */
export const invoices = pgTable(
  'invoices',
  {
    id: id(),
    userId: text('user_id').notNull(),
    providerRef: text('provider_ref').notNull().unique(),
    amount: integer('amount').notNull(),
    currency: text('currency').notNull(),
    status: text('status').$type<'paid' | 'open' | 'failed' | 'refunded'>().notNull(),
    periodStart: timestamp('period_start', { withTimezone: true }),
    periodEnd: timestamp('period_end', { withTimezone: true }),
    hostedUrl: text('hosted_url'),
    createdAt: createdAt(),
  },
  (t) => [index('invoices_user_idx').on(t.userId, t.createdAt)],
)

/** Webhook events already handled, so a provider's retries are applied once. */
export const billingEvents = pgTable('billing_events', {
  eventId: text('event_id').primaryKey(),
  type: text('type').notNull(),
  receivedAt: createdAt(),
})

// ---- Beta feedback (PRD Phase 7) ----
export const feedback = pgTable(
  'feedback',
  {
    id: id(),
    userId: text('user_id'),
    kind: text('kind').$type<'bug' | 'idea' | 'praise' | 'other'>().notNull(),
    message: text('message').notNull(),
    /** where in the app they were (path only: never content) */
    path: text('path').notNull().default(''),
    userAgent: text('user_agent').notNull().default(''),
    status: text('status').$type<'new' | 'triaged' | 'done'>().notNull().default('new'),
    createdAt: createdAt(),
  },
  (t) => [index('feedback_status_idx').on(t.status, t.createdAt)],
)

// ---- The public feed: likes, views and reader comments (FR-020/023) ----
// Dashboard time-range indexes on work_likes, work_views and follows live in migration 0016 (SQL only).
export const workLikes = pgTable(
  'work_likes',
  {
    workId: uuid('work_id')
      .notNull()
      .references(() => works.id),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.workId, t.userId] }), index('work_likes_user_idx').on(t.userId)],
)

/**
 * One view per reader per work per day. `viewer` is a user id, or for signed-out readers a keyed hash of address and
 * browser that changes daily: we count readers without being able to follow anyone around.
 */
export const workViews = pgTable(
  'work_views',
  {
    workId: uuid('work_id')
      .notNull()
      .references(() => works.id),
    viewer: text('viewer').notNull(),
    day: date('day').notNull(),
  },
  (t) => [primaryKey({ columns: [t.workId, t.viewer, t.day] })],
)

/** Comments readers leave on a published work: public, unlike the manuscript's anchored comments. */
export const readerComments = pgTable(
  'reader_comments',
  {
    id: id(),
    workId: uuid('work_id')
      .notNull()
      .references(() => works.id),
    authorId: text('author_id').notNull(),
    /** null for a top-level comment; replies are one level deep */
    parentId: uuid('parent_id'),
    /** paragraph comments (P-054): the published chapter and the block the comment sits beside; null = the whole work */
    chapterId: uuid('chapter_id'),
    blockId: text('block_id'),
    body: text('body').notNull(),
    editedAt: timestamp('edited_at', { withTimezone: true }),
    deletedAt: timestamp('deleted_at', { withTimezone: true }),
    deletedBy: text('deleted_by'),
    createdAt: createdAt(),
  },
  (t) => [
    index('reader_comments_work_idx').on(t.workId, t.createdAt),
    index('reader_comments_block_idx').on(t.chapterId, t.blockId),
    index('reader_comments_author_idx').on(t.authorId, t.createdAt),
  ],
)

// ---- Badges (PRD FR-025, §8.15/8.16): definitions are data; criteria are code, keyed by `code` ----
export const achievements = pgTable('achievements', {
  code: text('code').primaryKey(),
  name: text('name').notNull(),
  description: text('description').notNull(),
  criteriaVersion: integer('criteria_version').notNull().default(1),
  active: boolean('active').notNull().default(true),
  sortOrder: integer('sort_order').notNull().default(0),
  createdAt: createdAt(),
})

export const userAchievements = pgTable(
  'user_achievements',
  {
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    achievementCode: text('achievement_code')
      .notNull()
      .references(() => achievements.code),
    awardedAt: timestamp('awarded_at', { withTimezone: true }).notNull().defaultNow(),
    metadata: jsonb('metadata').notNull().default({}),
  },
  // Awarded once (no repeatable badges yet): the key makes a second award a no-op.
  (t) => [primaryKey({ columns: [t.userId, t.achievementCode] })],
)

/** Visits to an author's public page: one per visitor per day, keyed like `work_views` (no one can be followed). */
export const profileViews = pgTable(
  'profile_views',
  {
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    viewer: text('viewer').notNull(),
    day: date('day').notNull(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.viewer, t.day] })],
)
